#include <bits/stdc++.h>
using namespace std;

const int INF = INT_MAX;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;

    vector<int> vPositions, kPositions, otherPositions;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'V') {
            vPositions.push_back(i);
        } else if (s[i] == 'K') {
            kPositions.push_back(i);
        } else {
            otherPositions.push_back(i);
        }
    }

    int naV = vPositions.size();
    int naK = kPositions.size();
    int naO = otherPositions.size();

    vector<vector<vector<vector<int>>>> dp(naV + 1, vector<vector<vector<int>>>(naK + 1, vector<vector<int>>(naO + 1, vector<int>(2, INF))));
    vector<int> arrs[3];
    arrs[0] = vPositions;
    arrs[1] = kPositions;
    arrs[2] = otherPositions;

    int p[3][3][n];
    for (int x = 0; x < 3; x++) {
        for (int y = 0; y < 3; y++) {
            if (x != y) {
                for (int i = 0; i < arrs[x].size(); i++) {
                    for (int j = 0; j < arrs[y].size(); j++) {
                        if (arrs[y][j] < arrs[x][i]) {
                            p[x][y][i]++;
                        }
                    }
                }
            }
        }
    }

    dp[0][0][0][1] = 0;

    for (int i = 0; i <= naV; i++) {
        for (int j = 0; j <= naK; j++) {
            for (int k = 0; k <= naO; k++) {
                for (int q = 0; q < 2; q++) {
                    if (dp[i][j][k][q] != INF) {
                        if (i < naV) {
                            int cost = dp[i][j][k][q] + max(p[0][1][i] - j, 0) + max(p[0][2][i] - k, 0);
                            if (cost < dp[i + 1][j][k][0]) {
                                dp[i + 1][j][k][0] = cost;
                            }
                        }
                        if (j < naK && q == 1) {
                            int cost = dp[i][j][k][q] + max(p[1][0][j] - i, 0) + max(p[1][2][j] - k, 0);
                            if (cost < dp[i][j + 1][k][1]) {
                                dp[i][j + 1][k][1] = cost;
                            }
                        }
                        if (k < naO) {
                            int cost = dp[i][j][k][q] + max(p[2][0][k] - i, 0) + max(p[2][1][k] - j, 0);
                            if (cost < dp[i][j][k + 1][1]) {
                                dp[i][j][k + 1][1] = cost;
                            }
                        }
                    }
                }
            }
        }
    }

    int answer = min(dp[naV][naK][naO][0], dp[naV][naK][naO][1]);
    cout << answer << "\n";

    return 0;
}
